return ['domain'=>'free-analytics','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'bg_BG','project-id-version'=>'Free Analytics 1.0.0','pot-creation-date'=>'2026-10-31T10:44:39+00:00','po-revision-date'=>'2026-10-31 12:30+0200','messages'=>['Free Analytics'=>'Free Analytics','Simple, cookieless visitor statistics stored in your own database: visitors, page views, top content, traffic sources, contact clicks and form submissions. No IP addresses are stored.'=>'Проста статистика на посещенията без бисквитки, съхранявана в собствената Ви база данни: посетители, прегледи, най-гледано съдържание, източници на трафик, натискания за контакт и изпратени формуляри. IP адресите не се записват.','Visitor statistics'=>'Статистика на посещенията','Statistics'=>'Статистика','Today'=>'Днес','Yesterday'=>'Вчера','7 days'=>'7 дни','30 days'=>'30 дни','This month'=>'Този месец','Last month'=>'Миналия месец','12 months'=>'12 месеца','l, F j, Y'=>'l, j F Y г.','F j, Y'=>'j F Y г.','%1$s – %2$s'=>'%1$s – %2$s','Home page'=>'Начална страница','%s pp'=>'%s пр.п.','new'=>'ново','Sorry, you are not allowed to access this page.'=>'Нямате право да виждате тази страница.','Online now: %s'=>'Сега на сайта: %s','Change compared with %s'=>'Промяната е спрямо %s','Devices'=>'Устройства','Browsers'=>'Браузъри','Operating systems'=>'Операционни системи','These statistics use no cookies and store no IP addresses. A visitor is recognised only within one day, by an anonymous code that changes every night, so for a period of several days "Visitors" is the sum of each day\'s unique visitors. Data is kept for %d month. Logged-in users are not counted.'=>'Статистиката не използва бисквитки и не пази IP адреси. Посетителят се разпознава само в рамките на деня по анонимен код, който се сменя всяка нощ, затова при период от няколко дни „Посетители“ е сборът от уникалните посетители за всеки ден. Данните се пазят %d месец. Влезлите потребители не се броят.' . "\0" . 'Статистиката не използва бисквитки и не пази IP адреси. Посетителят се разпознава само в рамките на деня по анонимен код, който се сменя всяка нощ, затова при период от няколко дни „Посетители“ е сборът от уникалните посетители за всеки ден. Данните се пазят %d месеца. Влезлите потребители не се броят.','The web server passes the address of a proxy to WordPress instead of the visitor\'s (REMOTE_ADDR is an internal address and the request has X-Forwarded-For). All visitors would be counted as one. Configure the server to pass the real client IP (for example mod_remoteip or the nginx real_ip module).'=>'Сървърът подава на WordPress адреса на прокси, а не на посетителя (REMOTE_ADDR е вътрешен адрес, а заявката има X-Forwarded-For). Така всички посетители ще се броят като един. Настройте сървъра да подава реалния IP адрес (например mod_remoteip или модула real_ip на nginx).','Period'=>'Период','date rangefrom'=>'от','date rangeto'=>'до','Show'=>'Покажи','Visitors'=>'Посетители','sum of each day\'s unique visitors'=>'сбор от уникалните за всеки ден','unique for the day'=>'уникални за деня','Visits'=>'Посещения','a new one after 30 minutes of inactivity'=>'ново след 30 мин. без активност','Page views'=>'Прегледи на страници','Pages per visit'=>'Страници на посещение','Bounce rate'=>'Отпадане','visits with a single page'=>'посещения само с една страница','Phone calls'=>'Обаждания','clicks on phone numbers'=>'натискания на телефон','Form submissions'=>'Изпратени формуляри','successfully sent forms'=>'успешно изпратени','All contacts'=>'Всички контакти','phone, email, map, Viber, WhatsApp'=>'телефон, имейл, карта, Viber, WhatsApp','M Y'=>'M Y','M'=>'M','F Y'=>'F Y г.','n/j'=>'j.m','Visitors by hour'=>'Посетители по часове','Visitors by day'=>'Посетители по дни','Visitors by month'=>'Посетители по месеци','visitor'=>'посетител' . "\0" . 'посетители','page view'=>'преглед' . "\0" . 'прегледа','Show as a table'=>'Покажи като таблица','No data for the selected period.'=>'Няма данни за избрания период.','Most viewed: %s'=>'Най-гледани: %s','Contacts: phone, email, map and form submissions from the page.'=>'Контакти: обаждания, имейли, карта и формуляри от страницата.','Views'=>'Прегледи','Contacts'=>'Контакти','not published'=>'непубликувана','deleted'=>'изтрита','Most viewed pages'=>'Най-посещавани страници','Page'=>'Страница','Direct'=>'Директно','Traffic sources'=>'Източници на трафик','"Direct": typed address, bookmark, app, or a site that hides the referrer.'=>'„Директно“: въведен адрес, отметка, приложение или сайт, който скрива откъде идва посетителят.','Source'=>'Източник','Forms'=>'Формуляри','Campaigns (UTM)'=>'Кампании (UTM)','Campaign'=>'Кампания','Clicks on contact links and sent forms, with the pages where they happen most.'=>'Натискания на връзки за контакт и изпратени формуляри, с най-честите страници.','Type'=>'Вид','Count'=>'Брой','Missing pages (404)'=>'Липсващи страници (404)','Addresses that visitors open but that do not exist, for example removed content or broken links.'=>'Адреси, които посетителите отварят, но не съществуват, например премахнато съдържание или грешни връзки.','Address'=>'Адрес','Other'=>'Други','%s page view'=>'%s преглед' . "\0" . '%s прегледа','Visitors today'=>'Посетители днес','Visitors, 7 days'=>'Посетители, 7 дни','Contacts, 7 days'=>'Контакти, 7 дни','%s form submission'=>'%s изпратен формуляр' . "\0" . '%s изпратени формуляра','View statistics →'=>'Към статистиката →','Desktop'=>'Компютър','Mobile'=>'Телефон','Tablet'=>'Таблет','Page view'=>'Преглед','Phone call'=>'Обаждане','Email'=>'Имейл','Directions (map)'=>'Упътване (карта)','Form submission'=>'Изпратен формуляр','https://github.com/katsar0v/free-analytics'=>'https://github.com/katsar0v/free-analytics','Katsarov Design'=>'Katsarov Design','https://github.com/katsar0v'=>'https://github.com/katsar0v']];